  var DEFAULTS = {"depth":2,"labels":"fit","padding":2};

  var plot = sec.querySelector("svg.ck-plot");
  var cap = sec.querySelector(".ck-cap");
  if (!plot) { return; }

  /* One display-list entry as a real element. Attribute names are the SVG ones, so this
     stays a translator rather than a second place where treemap decisions live. */
  function node(m) {
    var e = document.createElementNS(NS, m.t), a = m.a, k, tip;
    for (k in a) { if (Object.hasOwn(a, k) && a[k] != null && a[k] !== "") { e.setAttribute(k, a[k]); } }
    if (m.s != null) { e.textContent = m.s; }
    if (m.ti != null) {
      tip = document.createElementNS(NS, "title");
      tip.textContent = m.ti;
      e.appendChild(tip);
    }
    return e;
  }

  /* A select hands back a string, so a stored depth of 3 and a default of 3 are a string
     and a number. Every lookup is built from String() so the two cannot disagree, and an
     unbuilt combination falls back to the one the card shipped drawn. */
  function keyOf(cfg) {
    var k = String(cfg.depth) + "|" + String(cfg.padding);
    return P.v[k] ? k : P.def;
  }

  function modeOf(cfg) {
    return cfg.labels === "all" || cfg.labels === "none" ? cfg.labels : "fit";
  }

  function render(cfg) {
    var V = P.v[keyOf(cfg)], mode = modeOf(cfg), i, m;
    if (!V) { return; }

    while (plot.firstChild) { plot.removeChild(plot.firstChild); }
    plot.setAttribute("viewBox", "0 0 " + V.W + " " + V.H);
    plot.setAttribute("aria-label", V.aria);

    for (i = 0; i < V.marks.length; i++) {
      m = V.marks[i];
      if (m.lm != null) {
        if (mode === "none") { continue; }
        if (mode === "fit" && m.lm === 1) { continue; }
      }
      plot.appendChild(node(m));
    }

    /* The caption is markup that was escaped value by value in Node; nothing from the
       data reaches it unescaped, which is why it may be assigned rather than built. */
    if (cap) { cap.innerHTML = V.cap; }
  }

  CK.settings(sec, DEFAULTS, render);
